// Photographic ground textures from Poly Haven (polyhaven.com, CC0), shrunk to 512 px and
// embedded as data URIs so they load when index.html is opened straight from disk:
//   asphalt  "Asphalt 04"  worn grey road surface      (roads)
//   tarmac   "Clean Asphalt"  dark fresh tarmac         (parking lots, decks, the hill road)
//   paving   "Concrete Pavement"  slab footpath          (pavements)
//   grass    "Leafy Grass", in greyscale: blade detail that the game tints green
// The first three each have a colour image and a normal map (surface relief for the lighting).
window.ROAD_TEXTURES = {
  asphalt: 'data:image/jpeg;base64,',
  asphaltNormal: 'data:image/jpeg;base64,',
  tarmac: 'data:image/jpeg;base64,',
  tarmacNormal: 'data:image/jpeg;base64,',
  paving: 'data:image/jpeg;base64,',
  pavingNormal: 'data:image/jpeg;base64,',
  grass: 'data:image/jpeg;base64,',
};
